const crypto = require("crypto");
const envelope = $json;
const body = envelope.body ?? envelope;
const headers = envelope.headers ?? {};
const signature = String(headers["x-ff-signature"] ?? "");
const timestamp = String(headers["x-ff-timestamp"] ?? "");
const nonce = String(headers["x-ff-nonce"] ?? "");
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error("Missing N8N_WEBHOOK_SECRET in n8n environment");
if (!signature || !timestamp || !nonce) throw new Error("Missing CP request signature headers");
if (!body.job_id || !body.correlation_id || !body.callback_url) throw new Error("Missing job_id, correlation_id, or callback_url");
if (body.workflow_type !== "creative_image_generation") throw new Error("Unexpected workflow_type");
const drift = Math.abs(Date.now() - Date.parse(timestamp));
if (!Number.isFinite(drift) || drift > 5 * 60 * 1000) throw new Error("CP request timestamp rejected");
const raw = JSON.stringify(body);
const expected = crypto.createHmac("sha256", secret).update(timestamp + "." + nonce + "." + raw).digest("hex");
const supplied = Buffer.from(signature, "hex");
const calculated = Buffer.from(expected, "hex");
if (supplied.length !== calculated.length || !crypto.timingSafeEqual(supplied, calculated)) throw new Error("Invalid CP request signature");
return [{ json: { cp: body, accepted: true, received_at: new Date().toISOString() } }];

const fs = require("fs");
const path = require("path");

const cp = $json.cp;
const payload = cp.payload ?? {};

const baseDir = path.resolve(String($env.BRAND_ASSETS_BASE_DIR || "/data/brand-assets"));

const idPattern = /^[a-z0-9][a-z0-9-]{0,63}$/;

const brandId = String(payload.brand_id || "future-oils");
const logoId = String(payload.logo_id || "primary");
const templateBackgroundId = String(payload.template_background_id || payload.background_id || "future-oils-classic");
const ratio = String(payload.ratio || "4:5");

if (!idPattern.test(brandId) || !idPattern.test(logoId) || !idPattern.test(templateBackgroundId)) {
  throw new Error("Invalid brand asset identifier");
}

if (!new Set(["4:5", "1:1", "9:16"]).has(ratio)) {
  throw new Error("Unsupported creative ratio");
}

const profilePath = path.resolve(baseDir, "brand-profile.json");

if (!profilePath.startsWith(baseDir + path.sep)) {
  throw new Error("Brand profile path escaped asset root");
}

const profile = JSON.parse(fs.readFileSync(profilePath, "utf8"));

if (profile.brand_id !== brandId) {
  throw new Error("Requested brand profile is unavailable");
}

function resolveAsset(relative) {
  if (!relative || typeof relative !== "string") {
    throw new Error("Brand asset is missing from profile");
  }

  const absolute = path.resolve(baseDir, relative);

  if (!absolute.startsWith(baseDir + path.sep)) {
    throw new Error("Brand asset path escaped asset root");
  }

  if (!fs.statSync(absolute).isFile()) {
    throw new Error("Brand asset file is unavailable: " + absolute);
  }

  return absolute;
}

function normalizeArabicDigits(value) {
  const arabicIndic = "٠١٢٣٤٥٦٧٨٩";
  const easternArabicIndic = "۰۱۲۳۴۵۶۷۸۹";

  return String(value || "").replace(/[٠-٩۰-۹]/g, (digit) => {
    const a = arabicIndic.indexOf(digit);
    if (a >= 0) return String(a);

    const e = easternArabicIndic.indexOf(digit);
    if (e >= 0) return String(e);

    return digit;
  });
}

function normalizeText(value) {
  return normalizeArabicDigits(value)
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[._/\\]+/g, " ")
    .replace(/[-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function compactText(value) {
  return normalizeText(value).replace(/\s+/g, "");
}

function getPayloadSearchText(payload) {
  return [
    payload.product_asset_id,
    payload.product_key,
    payload.product_code,
    payload.product_id,
    payload.sku,
    payload.product_sku,
    payload.product,
    payload.product_name,
    payload.title,
    payload.headline,
    payload.description,
    payload.size,
    payload.capacity,
    payload.volume,
    payload.package_size,
    payload.pack_size
  ]
    .filter((value) => value !== null && value !== undefined && String(value).trim())
    .map(String)
    .join(" ");
}

/**
 * Extract liter capacity from payload.
 * Supports:
 * 5L
 * 5 L
 * 5-liter
 * 5 liter
 * 5 litres
 * 5 ltr
 * 5 لتر
 * ٥ لتر
 */
function extractCapacityLiters(payload) {
  const explicitFields = [
    payload.capacity_liters,
    payload.capacity_litre,
    payload.volume_liters,
    payload.volume_litre,
    payload.liters,
    payload.litres,
    payload.size_liters,
    payload.size_litre,
    payload.pack_size_liters,
    payload.pack_size_litre
  ];

  for (const value of explicitFields) {
    const number = Number(normalizeArabicDigits(value));

    if (Number.isFinite(number) && number > 0 && number <= 100) {
      return number;
    }
  }

  const text = normalizeText(getPayloadSearchText(payload));

  const patterns = [
    /(?:^|\D)(\d+(?:\.\d+)?)\s*(?:l|lt|ltr|liter|liters|litre|litres)(?:\D|$)/i,
    /(?:^|\D)(\d+(?:\.\d+)?)\s*[- ]?\s*(?:l|lt|ltr)(?:\D|$)/i
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);

    if (match) {
      const number = Number(match[1]);

      if (Number.isFinite(number) && number > 0 && number <= 100) {
        return number;
      }
    }
  }

  /**
   * Fallback:
   * لو لم نجد وحدة L/لتر، نبحث عن رقم واضح من السعات المعروفة.
   * رتبنا 18 و13 و12 و10 قبل 1 و2 حتى لا يلتقط رقم 1 من 10 أو 12.
   */
  const knownSizes = [18, 13, 12, 10, 5, 4, 3, 2, 1];

  for (const size of knownSizes) {
    const re = new RegExp("(^|\\D)" + size + "(\\D|$)", "i");

    if (re.test(text)) {
      return size;
    }
  }

  return null;
}

function extractAllCapacityLiters(payload) {
  const found = new Set();

  const add = (value) => {
    const number = Number(normalizeArabicDigits(value));
    if (Number.isFinite(number) && number > 0 && number <= 100) {
      found.add(number);
    }
  };

  for (const value of [
    payload.capacity_liters,
    payload.capacity_litre,
    payload.volume_liters,
    payload.volume_litre,
    payload.liters,
    payload.litres,
    payload.size_liters,
    payload.size_litre,
    payload.pack_size_liters,
    payload.pack_size_litre
  ]) {
    if (Array.isArray(value)) {
      for (const item of value) add(item);
    } else {
      add(value);
    }
  }

  const text = normalizeText(getPayloadSearchText(payload));
  const patterns = [
    /(?:^|\D)(\d+(?:\.\d+)?)\s*(?:l|lt|ltr|liter|liters|litre|litres)(?:\D|$)/gi,
    /(?:^|\D)(\d+(?:\.\d+)?)\s*[- ]?\s*(?:l|lt|ltr)(?:\D|$)/gi
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(text))) {
      add(match[1]);
    }
  }

  const knownSizes = [18, 13, 12, 10, 5, 4, 3, 2, 1];
  for (const size of knownSizes) {
    const re = new RegExp("(^|[^0-9])" + size + "([^0-9]|$)", "i");
    if (re.test(text)) found.add(size);
  }

  return [...found].sort((a, b) => a - b);
}

function normalizeProductAssetList(value) {
  if (Array.isArray(value)) {
    return value.flatMap((item) => normalizeProductAssetList(item));
  }

  if (value === null || value === undefined) return [];

  return String(value)
    .split(/[;,|]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function getExplicitProductAssetIds(payload) {
  return [
    ...normalizeProductAssetList(payload.product_asset_ids),
    ...normalizeProductAssetList(payload.product_assets),
    ...normalizeProductAssetList(payload.product_ids),
    ...normalizeProductAssetList(payload.products)
  ];
}

function sortProductIdsByCapacity(productIds) {
  return [...productIds].sort((a, b) => {
    const am = String(a).match(/(\d+(?:\.\d+)?)/);
    const bm = String(b).match(/(\d+(?:\.\d+)?)/);
    const an = am ? Number(am[1]) : Number.MAX_SAFE_INTEGER;
    const bn = bm ? Number(bm[1]) : Number.MAX_SAFE_INTEGER;
    return an - bn || String(a).localeCompare(String(b));
  });
}

function productCandidateText(productId, product) {
  return [
    productId,
    product?.id,
    product?.key,
    product?.sku,
    product?.code,
    product?.name,
    product?.title,
    product?.label,
    product?.description,
    product?.size,
    product?.capacity,
    product?.volume,
    product?.package_size,
    product?.pack_size,
    product?.file
  ]
    .filter((value) => value !== null && value !== undefined && String(value).trim())
    .map(String)
    .join(" ");
}

function productHasCapacity(productId, product, capacityLiters) {
  if (!capacityLiters) return false;

  const numericFields = [
    product?.capacity_liters,
    product?.capacity_litre,
    product?.volume_liters,
    product?.volume_litre,
    product?.liters,
    product?.litres,
    product?.size_liters,
    product?.size_litre,
    product?.pack_size_liters,
    product?.pack_size_litre
  ];

  for (const value of numericFields) {
    const number = Number(normalizeArabicDigits(value));

    if (Number.isFinite(number) && number === capacityLiters) {
      return true;
    }
  }

  const text = normalizeText(productCandidateText(productId, product));
  const compact = compactText(productCandidateText(productId, product));

  const size = String(capacityLiters).replace(/\.0+$/, "");

  const capacityPatterns = [
    new RegExp("(^|\\D)" + size + "\\s*(l|lt|ltr|liter|liters|litre|litres)(\\D|$)", "i"),
    new RegExp("(^|\\D)" + size + "\\s*لتر(\\D|$)", "i")
  ];

  if (capacityPatterns.some((pattern) => pattern.test(text))) {
    return true;
  }

  const compactPatterns = [
    size + "l",
    size + "lt",
    size + "ltr",
    size + "liter",
    size + "litre",
    size + "liters",
    size + "litres",
    size + "لتر",
    size + "ليتر"
  ];

  if (compactPatterns.some((token) => compact.includes(token))) {
    return true;
  }

  /**
   * Fallback مضبوط:
   * يطابق الرقم كجزء مستقل في product id أو اسم الملف أو الاسم.
   */
  const standaloneNumber = new RegExp("(^|\\D)" + size + "(\\D|$)", "i");

  return standaloneNumber.test(text);
}

function scoreProductMatch(productId, product, payload, capacityLiters) {
  const searchText = normalizeText(getPayloadSearchText(payload));
  const searchCompact = compactText(getPayloadSearchText(payload));

  const candidateText = normalizeText(productCandidateText(productId, product));
  const candidateCompact = compactText(productCandidateText(productId, product));

  let score = 0;
  const reasons = [];

  const explicitKeys = [
    payload.product_asset_id,
    payload.product_key,
    payload.product_code,
    payload.product_id,
    payload.sku,
    payload.product_sku
  ]
    .filter((value) => value !== null && value !== undefined && String(value).trim())
    .map((value) => compactText(value));

  const productIdCompact = compactText(productId);

  for (const key of explicitKeys) {
    if (!key) continue;

    if (productIdCompact === key) {
      score += 1000;
      reasons.push("exact explicit key match");
    } else if (candidateCompact.includes(key) || key.includes(productIdCompact)) {
      score += 600;
      reasons.push("partial explicit key match");
    }
  }

  if (capacityLiters && productHasCapacity(productId, product, capacityLiters)) {
    score += 300;
    reasons.push("capacity match " + capacityLiters + "L");
  }

  /**
   * Product/category hints.
   */
  const categoryWords = [
    "sunflower",
    "refined",
    "oil",
    "زيت",
    "دوار",
    "الشمس"
  ];

  for (const word of categoryWords) {
    if (searchCompact.includes(compactText(word)) && candidateCompact.includes(compactText(word))) {
      score += 20;
      reasons.push("category word match: " + word);
    }
  }

  /**
   * Prefer marketing-approved products.
   */
  if (score > 0 && product?.approved_for_marketing === true) {
    score += 25;
    reasons.push("approved for marketing");
  }

  return {
    productId,
    product,
    score,
    reasons
  };
}

function findProductAssetId(profile, payload) {
  const products = profile.products || {};
  const productIds = Object.keys(products);

  if (!productIds.length) {
    return {
      product_asset_id: null,
      reason: "brand profile has no products",
      capacity_liters: null,
      candidates: []
    };
  }

  /**
   * 1. Exact product_asset_id if provided.
   */
  const explicitProductAssetId = String(payload.product_asset_id || "").trim();

  if (explicitProductAssetId) {
    const normalizedExplicit = compactText(explicitProductAssetId);

    const exactId = productIds.find((id) => compactText(id) === normalizedExplicit);

    if (exactId) {
      return {
        product_asset_id: exactId,
        reason: "matched explicit product_asset_id",
        capacity_liters: extractCapacityLiters(payload),
        candidates: [{ productId: exactId, score: 1000, reasons: ["explicit product_asset_id"] }]
      };
    }
  }

  const capacityLiters = extractCapacityLiters(payload);

  const scored = productIds
    .map((productId) => scoreProductMatch(productId, products[productId], payload, capacityLiters))
    .filter((candidate) => candidate.score > 0)
    .sort((a, b) => b.score - a.score);

  if (!scored.length) {
    return {
      product_asset_id: null,
      reason: "no product matched payload text or capacity",
      capacity_liters: capacityLiters,
      candidates: []
    };
  }

  const best = scored[0];

  return {
    product_asset_id: best.productId,
    reason: "selected highest scoring product match",
    capacity_liters: capacityLiters,
    candidates: scored.slice(0, 5).map((candidate) => ({
      productId: candidate.productId,
      score: candidate.score,
      reasons: candidate.reasons
    }))
  };
}

const logoRelative = profile.logos?.[logoId];

if (!logoRelative) {
  throw new Error("Requested logo asset is unavailable");
}

const templateBackgroundEntry = profile.template_backgrounds?.[templateBackgroundId];
const templateBackgroundRelative = String(
  typeof templateBackgroundEntry === "string"
    ? templateBackgroundEntry
    : templateBackgroundEntry?.file || profile.template_background || "logo/background.png"
);
let templateBackgroundPath;

try {
  templateBackgroundPath = resolveAsset(templateBackgroundRelative);
} catch {
  throw new Error("Fixed template background is unavailable");
}

function findProductAssetIds(profile, payload) {
  const products = profile.products || {};
  const productIds = Object.keys(products);
  const explicitIds = getExplicitProductAssetIds(payload);
  const wantsAll =
    String(payload.layout_mode || "").toLowerCase() === "all" ||
    String(payload.product_selection || "").toLowerCase() === "all" ||
    explicitIds.some((id) => ["all", "all-products", "all_products"].includes(compactText(id)));

  if (wantsAll) {
    const approvedIds = sortProductIdsByCapacity(
      productIds.filter((id) => products[id]?.approved_for_marketing === true)
    );

    return {
      product_asset_ids: approvedIds,
      reason: "selected all approved marketing products",
      capacity_liters: approvedIds.map((id) => {
        const match = String(id).match(/(\d+(?:\.\d+)?)/);
        return match ? Number(match[1]) : null;
      }).filter((value) => value !== null),
      candidates: approvedIds.map((productId) => ({ productId, score: 1000, reasons: ["all approved products"] }))
    };
  }

  const selected = [];
  const candidates = [];

  for (const explicitId of explicitIds) {
    const normalized = compactText(explicitId);
    const exactId = productIds.find((id) => compactText(id) === normalized);

    if (exactId && !selected.includes(exactId)) {
      selected.push(exactId);
      candidates.push({ productId: exactId, score: 1000, reasons: ["explicit product_asset_ids"] });
    }
  }

  const capacities = extractAllCapacityLiters(payload);

  for (const capacityLiters of capacities) {
    const scored = productIds
      .map((productId) => scoreProductMatch(productId, products[productId], payload, capacityLiters))
      .filter((candidate) => candidate.score > 0 && productHasCapacity(candidate.productId, candidate.product, capacityLiters))
      .sort((a, b) => b.score - a.score);

    const best = scored[0];
    if (best && !selected.includes(best.productId)) {
      selected.push(best.productId);
      candidates.push({ productId: best.productId, score: best.score, reasons: best.reasons });
    }
  }

  if (selected.length) {
    return {
      product_asset_ids: sortProductIdsByCapacity(selected),
      reason: selected.length > 1 ? "selected multiple product assets" : "selected single product asset",
      capacity_liters: capacities,
      candidates
    };
  }

  if (capacities.length) {
    return {
      product_asset_ids: [],
      reason: "requested product capacities are unavailable: " + capacities.map((size) => size + "L").join(", "),
      capacity_liters: capacities,
      candidates
    };
  }

  const single = findProductAssetId(profile, payload);

  return {
    product_asset_ids: single.product_asset_id ? [single.product_asset_id] : [],
    reason: single.reason,
    capacity_liters: single.capacity_liters ? [single.capacity_liters] : [],
    candidates: single.candidates || []
  };
}

const productResolution = findProductAssetIds(profile, payload);
const productAssetIds = productResolution.product_asset_ids || [];
const productAssets = productAssetIds.map((productAssetId) => {
  const product = profile.products?.[productAssetId];

  if (!product) {
    throw new Error("Requested product asset is unavailable: " + productAssetId);
  }

  if (product.approved_for_marketing !== true) {
    throw new Error(product.restriction || "Requested product asset is not approved for marketing: " + productAssetId);
  }

  return {
    product_asset_id: productAssetId,
    product_path: resolveAsset(product.file),
    file: product.file
  };
});

const primaryProduct = productAssets[0] || null;

return [
  {
    json: {
      cp,
      asset_contract: {
        brand_id: brandId,
        logo_id: logoId,
        product_asset_id: primaryProduct ? primaryProduct.product_asset_id : null,
        product_asset_ids: productAssets.map((product) => product.product_asset_id),
        product_resolution: productResolution,
        template_background_id: templateBackgroundId,
        ratio,
        profile_version: profile.schema_version,
        brand_theme: profile.brand_theme || {},
        layout_rules: profile.layout_rules || {},
        logo_path: resolveAsset(logoRelative),
        product_path: primaryProduct ? primaryProduct.product_path : null,
        product_paths: productAssets.map((product) => product.product_path),
        products: productAssets,
        template_background_path: templateBackgroundPath
      }
    }
  }
];

const sharp = require("sharp");
const fs = require("fs");
const path = require("path");

function clampNumber(value, fallback, min, max) {
  const number = Number(value);

  if (!Number.isFinite(number)) return fallback;

  return Math.min(max, Math.max(min, number));
}

const resolved = $("Resolve Brand Assets").item.json;
const payload = resolved.cp?.payload ?? {};
const contract = resolved.asset_contract;

if (!contract) {
  throw new Error("Missing asset_contract from Resolve Brand Assets");
}

if (!contract.template_background_path || !fs.existsSync(contract.template_background_path)) {
  throw new Error("Fixed template background is unavailable");
}

const productPaths = Array.isArray(contract.product_paths) && contract.product_paths.length
  ? contract.product_paths
  : contract.product_path
    ? [contract.product_path]
    : [];

if (!productPaths.length) {
  throw new Error(contract.product_resolution?.reason || "Product image is required for fixed template composition");
}

for (const productPath of productPaths) {
  if (!fs.existsSync(productPath)) {
    throw new Error("Product file does not exist: " + productPath);
  }
}

const dimensions = {
  "4:5": [1080, 1350],
  "1:1": [1080, 1080],
  "9:16": [1080, 1920]
}[contract.ratio];

if (!dimensions) {
  throw new Error("Unsupported ratio: " + contract.ratio);
}

const [width, height] = dimensions;
const backgroundBuffer = fs.readFileSync(contract.template_background_path);

try {
  await sharp(backgroundBuffer).metadata();
} catch (error) {
  throw new Error("Sharp could not read fixed template background: " + error.message);
}

async function trimProductBuffer(productPath) {
  const sourceBuffer = fs.readFileSync(productPath);

  try {
    await sharp(sourceBuffer).metadata();
  } catch (error) {
    throw new Error("Sharp could not read product image: " + error.message);
  }

  return sharp(sourceBuffer)
    .trim({
      threshold: 10,
      background: { r: 0, g: 0, b: 0, alpha: 0 }
    })
    .png()
    .toBuffer();
}

function getProductFrame(targetWidth, targetHeight) {
  return {
    x: Math.round(targetWidth * 0.2086),
    y: Math.round(targetHeight * 0.2290),
    w: Math.round(targetWidth * 0.6105),
    h: Math.round(targetHeight * 0.6469)
  };
}

async function buildProductComposite(targetWidth, targetHeight, productPath) {
  const frame = getProductFrame(targetWidth, targetHeight);
  const baseline = frame.y + frame.h;
  const trimmedBuffer = await trimProductBuffer(productPath);
  const productBuffer = await sharp(trimmedBuffer)
    .resize({
      width: frame.w,
      height: frame.h,
      fit: "inside",
      withoutEnlargement: false
    })
    .png()
    .toBuffer();
  const productMeta = await sharp(productBuffer).metadata();
  const productWidth = productMeta.width || 0;
  const productHeight = productMeta.height || 0;

  return {
    input: productBuffer,
    left: Math.round(frame.x + (frame.w - productWidth) / 2),
    top: Math.round(baseline - productHeight)
  };
}

async function renderJpeg(productPath, targetWidth, targetHeight, quality) {
  const productComposite = await buildProductComposite(targetWidth, targetHeight, productPath);

  return sharp(backgroundBuffer)
    .resize(targetWidth, targetHeight, {
      fit: "cover",
      position: "center"
    })
    .composite([productComposite])
    .flatten({
      background: "#ffffff"
    })
    .jpeg({
      quality,
      mozjpeg: true
    })
    .toBuffer();
}
const maxCallbackImageBytes = clampNumber(
  payload.max_callback_image_bytes,
  650 * 1024,
  180 * 1024,
  2 * 1024 * 1024
);
const maxCallbackTotalImageBytes = clampNumber(
  payload.max_callback_total_image_bytes,
  5 * 1024 * 1024,
  1 * 1024 * 1024,
  8 * 1024 * 1024
);
const perImageLimit = Math.max(
  180 * 1024,
  Math.min(maxCallbackImageBytes, Math.floor(maxCallbackTotalImageBytes / productPaths.length))
);

async function renderProductFile(productPath, index) {
  let outputWidth = width;
  let outputHeight = height;
  let finalBuffer = null;
  let finalQuality = null;

  for (const quality of [82, 78, 74, 70, 66, 62, 58, 54, 50, 46, 42]) {
    const candidate = await renderJpeg(productPath, width, height, quality);
    finalBuffer = candidate;
    finalQuality = quality;
    if (candidate.length <= perImageLimit) break;
  }

  if (finalBuffer.length > perImageLimit) {
    outputWidth = Math.round(width * 0.85);
    outputHeight = Math.round(height * 0.85);

    for (const quality of [78, 74, 70, 66, 62, 58, 54, 50, 46, 42]) {
      const candidate = await renderJpeg(productPath, outputWidth, outputHeight, quality);
      finalBuffer = candidate;
      finalQuality = quality;
      if (candidate.length <= perImageLimit) break;
    }
  }

  const productAssetId = contract.product_asset_ids?.[index] || `product-${index + 1}`;
  return {
    name: `creative-${resolved.cp.job_id}-${productAssetId}.jpg`,
    mime_type: "image/jpeg",
    data_base64: finalBuffer.toString("base64"),
    size_bytes: finalBuffer.length,
    width: outputWidth,
    height: outputHeight,
    quality: finalQuality,
    product_asset_id: productAssetId,
    position: index + 1
  };
}

const composedFiles = [];
for (let index = 0; index < productPaths.length; index++) {
  composedFiles.push(await renderProductFile(productPaths[index], index));
}

return [
  {
    json: {
      cp: resolved.cp,
      asset_contract: contract,
      provider_creation_id: String(resolved.cp.job_id) + "_fixed_template",
      composed_file: composedFiles[0],
      composed_files: composedFiles,
      product_layout: {
        mode: "separate-images",
        product_count: productPaths.length,
        product_asset_ids: contract.product_asset_ids || []
      },
      template_background_source: path.basename(contract.template_background_path)
    }
  }
];

const crypto = require("crypto");

function removeUndefined(value) {
  if (Array.isArray(value)) return value.map(removeUndefined);
  if (value && typeof value === "object") {
    const cleaned = {};
    for (const [key, val] of Object.entries(value)) {
      if (val !== undefined) cleaned[key] = removeUndefined(val);
    }
    return cleaned;
  }
  return value;
}

const item = $json;
const secret = $env.PLATFORM_CALLBACK_SECRET;

if (!secret) throw new Error("Missing PLATFORM_CALLBACK_SECRET in n8n environment");
if (!item.cp?.callback_url) throw new Error("Missing callback_url from CP payload");

const composedFiles = Array.isArray(item.composed_files) && item.composed_files.length
  ? item.composed_files
  : item.composed_file?.data_base64
    ? [item.composed_file]
    : [];

if (!composedFiles.length || composedFiles.some((file) => !file?.data_base64)) {
  throw new Error("Missing composed image data_base64");
}

const timestamp = new Date().toISOString();
const nonce = "n8n_composed_images_" + Date.now() + "_" + Math.random().toString(36).slice(2);
const creationId = String(item.provider_creation_id || item.cp.job_id);

const files = composedFiles.map((composed, index) => ({
  file_id: creationId + "_composed_" + (index + 1),
  type: "image",
  name: composed.name,
  mime_type: composed.mime_type,
  data_base64: composed.data_base64,
  size_bytes: composed.size_bytes,
  width: composed.width,
  height: composed.height,
  source: "n8n-sharp-compositor",
  product_asset_id: composed.product_asset_id || null,
  position: composed.position || index + 1
}));

const publicFiles = files.map(({ data_base64, ...file }) => file);
const publicAssetContract = {
  brand_id: item.asset_contract?.brand_id || null,
  logo_id: item.asset_contract?.logo_id || null,
  product_asset_id: item.asset_contract?.product_asset_id || null,
  product_asset_ids: item.asset_contract?.product_asset_ids || [],
  ratio: item.asset_contract?.ratio || null,
  profile_version: item.asset_contract?.profile_version || null,
  template_background_source: item.template_background_source || null
};

const callbackBody = removeUndefined({
  job_id: item.cp.job_id,
  correlation_id: item.cp.correlation_id,
  idempotency_key: item.cp.idempotency_key,
  workflow_type: "creative_image_generation",
  workflow_version: "creative-image-sharp-v2-multi-file",
  status: "completed",
  current_step: files.length === 1 ? "Branded image composed and ready for review" : `${files.length} branded images composed and ready for review`,
  nonce,
  signature_timestamp: timestamp,
  signature: "",
  outputs: {
    provider: "fixed-template-sharp",
    asset_contract: publicAssetContract,
    product_layout: item.product_layout,
    files: publicFiles
  },
  files,
  warnings: []
});

const raw = JSON.stringify(callbackBody);
const signature = crypto
  .createHmac("sha256", secret)
  .update(timestamp + "." + nonce + "." + raw)
  .digest("hex");

return [{
  json: {
    callback_url: item.cp.callback_url,
    callback_headers: { signature, timestamp, nonce },
    callback_body: callbackBody,
    callback_debug: {
      body_size_bytes: Buffer.byteLength(raw, "utf8"),
      file_count: files.length,
      total_file_size_bytes: composedFiles.reduce((total, file) => total + Number(file.size_bytes || 0), 0),
      file_names: composedFiles.map((file) => file.name),
      has_body_nonce: true,
      has_body_signature_timestamp: true,
      has_body_signature_field: true
    }
  }
}];
